1: // 真实后端请求封装：注入 zhi-project-id 头、Bearer token、解包 {code,msg,data}
2: export interface RequestOptions {
3:   method?: 'GET' | 'POST' | 'PUT' | 'DELETE'
4:   data?: unknown
5:   token?: string | false
6:   projectId?: string
7:   raw?: boolean
8:   baseUrl?: string
9: }
10: export interface TransportInput {
11:   url: string
12:   method: NonNullable<RequestOptions['method']>
13:   data?: unknown
14:   header: Record<string, string>
15:   timeout: number
16: }
17: export type Transport = (input: TransportInput) => Promise<{ statusCode: number; data: unknown }>
18: export interface Envelope<T> { code: number; msg: string; data: T }
19: export interface RequestConfig { baseUrl: string | (() => string); projectId: string | (() => string); getToken?: () => string | undefined }
20: 
21: function resolveConfigValue(value: string | (() => string)): string {
22:   return typeof value === 'function' ? value() : value
23: }
24: 
25: // 兼容旧签名：createRequest(transport, baseUrlString) -> 纯透传旧行为
26: // 新签名：createRequest(transport, configObject) -> 注入头 + 解包
27: export function createRequest(transport: Transport, baseUrlOrConfig: string | RequestConfig) {
28:   const legacy = typeof baseUrlOrConfig === 'string'
29:   const config: RequestConfig = legacy ? { baseUrl: baseUrlOrConfig, projectId: 'suzhufang' } : baseUrlOrConfig
30:   return async function request<T>(path: string, options: RequestOptions = {}): Promise<T> {
31:     const baseUrl = options.baseUrl ?? resolveConfigValue(config.baseUrl)
32:     if (!baseUrl) throw new Error('真实接口未配置：请设置 VITE_API_BASE_URL（推荐 /api）')
33:     const header: Record<string, string> = { 'Content-Type': 'application/json' }
34:     if (!legacy) {
35:       const useToken = options.token === false ? undefined : (options.token || config.getToken?.())
36:       header['zhi-project-id'] = options.projectId ?? resolveConfigValue(config.projectId)
37:       if (useToken) header.Authorization = `Bearer ${useToken}`
38:     } else if (options.token) {
39:       header.Authorization = `Bearer ${options.token}`
40:     }
41:     const response = await transport({
42:       url: `${baseUrl.replace(/\/$/, '')}/${path.replace(/^\//, '')}`,
43:       method: options.method ?? 'GET',
44:       data: options.data,
45:       header,
46:       timeout: 20000,
47:     })
48:     if (response.statusCode < 200 || response.statusCode >= 300) {
49:       const body = response.data as Envelope<unknown> | undefined
50:       const msg = body && typeof body === 'object' && 'msg' in body ? String(body.msg) : ''
51:       throw new Error(msg || `请求失败（HTTP ${response.statusCode}）`)
52:     }
53:     if (legacy || options.raw) return response.data as T
54:     const body = response.data as Envelope<T>
55:     if (body && typeof body === 'object' && 'code' in body) {
56:       if (body.code !== 200) throw new Error(body.msg || `业务异常（code ${body.code}）`)
57:       return body.data
58:     }
59:     return response.data as T
60:   }
61: }
62: 
63: export const uniTransport: Transport = input => new Promise((resolve, reject) => {
64:   uni.request({
65:     url: input.url,
66:     method: input.method as never,
67:     data: input.data as Record<string, unknown> | undefined,
68:     header: input.header,
69:     timeout: input.timeout,
70:     success: result => resolve({ statusCode: result.statusCode, data: result.data }),
71:     fail: result => reject(new Error(result.errMsg?.includes('timeout') ? '请求超时，请重试' : '网络连接失败，请重试')),
72:   })
73: })
74: 
75: const TOKEN_KEY = 'flood-token-v1'
76: export function getToken(): string | undefined {
77:   try { const t = uni.getStorageSync(TOKEN_KEY); return typeof t === 'string' && t ? t : undefined } catch { return undefined }
78: }
79: export function setToken(token: string) { try { uni.setStorageSync(TOKEN_KEY, token) } catch { /* ignore */ } }
80: export function clearToken() { try { uni.removeStorageSync(TOKEN_KEY) } catch { /* ignore */ } }
81: 
82: type EnvRecord = Record<string, string | undefined>
83: 
84: function readEnv(): EnvRecord {
85:   return import.meta.env as EnvRecord
86: }
87: 
88: /** 每次读取 import.meta.env，便于单测 stub 与 .env.test 隔离 */
89: export function getApiBase(): string {
90:   const env = readEnv()
91:   return env.VITE_API_BASE_URL ?? env.VITE_AUTH_BASE_URL ?? ''
92: }
93: 
94: export function getProjectId(): string {
95:   return readEnv().VITE_PROJECT_ID ?? 'suzhufang'
96: }
97: 
98: export function isConfigured() {
99:   return Boolean(getApiBase())
100: }
101: 
102: /** 网关图形验证码：GET /v2.0/code（与 main 分支 getCodeImg → /api/v2.0/code 一致） */
103: export interface LoginCaptchaPayload {
104:   enabled: boolean
105:   uuid?: string
106:   imageDataUrl?: string
107: }
108: 
109: export async function fetchLoginCaptcha(): Promise<LoginCaptchaPayload> {
110:   // 图形验证码仅暴露于后端网关，demo 模式下也走同源 /api 反代（nginx 已代理 /api → 网关）。
111:   const apiBase = getApiBase() || '/api'
112:   const url = `${apiBase.replace(/\/$/, '')}/v2.0/code`
113:   const response = await uniTransport({
114:     url,
115:     method: 'GET',
116:     header: { Accept: 'application/json, text/plain, */*', 'zhi-project-id': getProjectId() },
117:     timeout: 20000,
118:   })
119:   if (response.statusCode < 200 || response.statusCode >= 300) {
120:     throw new Error(`验证码加载失败（HTTP ${response.statusCode}）`)
121:   }
122:   const body = response.data as {
123:     code?: number
124:     msg?: string
125:     captchaOnOff?: boolean
126:     uuid?: string
127:     data?: string
128:   } | null
129:   if (body && typeof body === 'object' && 'code' in body && body.code !== 200) {
130:     throw new Error(body.msg || '验证码加载失败')
131:   }
132:   const enabled = body?.captchaOnOff !== false && Boolean(body?.uuid && body?.data)
133:   if (!enabled) return { enabled: false }
134:   const raw = String(body!.data)
135:   const imageDataUrl = raw.startsWith('data:') ? raw : `data:image/jpeg;base64,${raw}`
136:   return { enabled: true, uuid: String(body!.uuid), imageDataUrl }
137: }
138: // 统一网关前缀（/api + /v2.0/...，对齐 main 分支 request 封装）
139: export const request = createRequest(uniTransport, {
140:   baseUrl: getApiBase,
141:   projectId: getProjectId,
142:   getToken,
143: })
144: /** @deprecated 与 request 同源，保留别名避免旧引用报错 */
145: export const authRequest = request
146: 
147: /**
148:  * H5 带鉴权下载文件流（PDF 等）。
149:  * window.open 直接导航不会携带 Authorization 头，后端会返回 401「令牌不能为空」；
150:  * 这里用原生 fetch 手动注入 Bearer + zhi-project-id，拿到 blob 后用临时 <a download> 触发下载。
151:  */
152: export async function downloadFileWithAuth(path: string, filename: string): Promise<void> {
153:   const apiBase = getApiBase()
154:   if (!apiBase) throw new Error('真实接口未配置：请设置 VITE_API_BASE_URL')
155:   const url = `${apiBase.replace(/\/$/, '')}/${path.replace(/^\//, '')}`
156:   const headers: Record<string, string> = { 'zhi-project-id': getProjectId() }
157:   const token = getToken()
158:   if (token) headers.Authorization = `Bearer ${token}`
159:   const resp = await fetch(url, { headers })
160:   if (!resp.ok) {
161:     let msg = `下载失败（HTTP ${resp.status}）`
162:     try { const j = await resp.json(); if (j && j.msg) msg = String(j.msg) } catch { /* 非 JSON 错误体，保留默认文案 */ }
163:     throw new Error(msg)
164:   }
165:   const blob = await resp.blob()
166:   const objectUrl = URL.createObjectURL(blob)
167:   const a = document.createElement('a')
168:   a.href = objectUrl
169:   a.download = filename
170:   document.body.appendChild(a)
171:   a.click()
172:   a.remove()
173:   setTimeout(() => URL.revokeObjectURL(objectUrl), 1500)
174: }

(End of file - total 174 lines)
</content>"}]

