5: import { isRef8443 } from '../../utils/ref8443'
6: import { useFloodStore, type FloodRecord, type InspectionType, type HistoryKind } from '../../stores/flood'
7: import { demoUser, levelTone, ticketPlaces, ticketTitles, titles } from '../../types/inspection'
8: import { toastError } from '../../utils/notify'
9: import useZPaging from 'z-paging/components/z-paging/js/hooks/useZPaging.js'
10: 
11: const store = useFloodStore()
12: type FilterKey = 'all' | 'draft' | 'submitted' | 'rescue'
13: const tab = ref<InspectionType>('pre')
14: const filter = ref<FilterKey>('all')
15: const rows = ref<FloodRecord[]>([])
16: const counts = ref<{ all: number; rescue: number; draft: number; submitted: number }>({ all: 0, rescue: 0, draft: 0, submitted: 0 })
17: interface Paging { completeByTotal(items: FloodRecord[], total: number): Promise<unknown>; complete(value: false): Promise<unknown>; reload(): Promise<unknown> }
18: const paging = ref<Paging>()
19: 
20: /* 汛中巡检页签额外归入求援工单，与归档截图中「全部工单(8) / 救援工单(2)」的分组一致 */
21: const tabKinds = computed<HistoryKind[]>(() => tab.value === 'mid' ? ['mid', 'rescue'] : [tab.value])
22: const queryKinds = computed<HistoryKind[]>(() => filter.value === 'rescue' ? ['rescue'] : tabKinds.value)
23: const queryStatus = computed<'all' | 'draft' | 'submitted'>(() => filter.value === 'draft' ? 'draft' : filter.value === 'submitted' ? 'submitted' : 'all')
24: const queryKey = computed(() => `${tab.value}:${filter.value}`)
25: useZPaging(paging)
26: let activeRequest = 0
27: 
28: async function query(pageNum: number, pageSize: number) {
29:   const request = ++activeRequest
30:   const key = queryKey.value
31:   const target = paging.value
32:   try {
33:     const result = await store.fetchHistoryPage({ pageNum, pageSize, kinds: queryKinds.value, status: queryStatus.value })
34:     if (request !== activeRequest || key !== queryKey.value) return
35:     await target?.completeByTotal(result.items, result.total)
36:   } catch (cause) {
37:     if (request !== activeRequest || key !== queryKey.value) return
38:     toastError(cause instanceof Error ? cause.message : '加载失败，请重试')
39:     await target?.complete(false).catch(() => {})
40:   }
41: }
42: async function refreshCounts() {
43:   try {
44:     const [all, rescue, draft, submitted] = await Promise.all([
45:       store.countHistory({ kinds: tabKinds.value, status: 'all' }),
46:       store.countHistory({ kinds: ['rescue'], status: 'all' }),
47:       store.countHistory({ kinds: tabKinds.value, status: 'draft' }),
48:       store.countHistory({ kinds: tabKinds.value, status: 'submitted' }),
49:     ])
50:     counts.value = { all, rescue, draft, submitted }
51:   } catch { counts.value = { all: 0, rescue: 0, draft: 0, submitted: 0 } }
52: }
53: function selectTab(value: InspectionType) {
54:   if (tab.value === value) return
55:   tab.value = value
56:   filter.value = 'all'
57:   rows.value = []
58:   refreshCounts()
59: }
60: function selectFilter(value: FilterKey) {
61:   filter.value = value
62:   rows.value = []
63: }
64: 
65: function open(item: FloodRecord) {
66:   if (item.status === 'draft') { uni.navigateTo({ url: `/pages/inspection/index?kind=${item.kind}` }); return }
67:   uni.navigateTo({ url: `/pages/detail/index?id=${encodeURIComponent(item.id)}&kind=${encodeURIComponent(item.kind)}` })
68: }
69: function viewDraft(item: FloodRecord) {
70:   uni.navigateTo({ url: `/pages/detail/index?id=${encodeURIComponent(item.id)}&kind=${encodeURIComponent(item.kind)}` })
71: }
72: function pad(value: number) { return String(value).padStart(2, '0') }
73: function formatDateTime(iso: string) {
74:   const date = new Date(iso)
75:   if (Number.isNaN(date.getTime())) return '—'
76:   return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())} ${pad(date.getHours())}:${pad(date.getMinutes())}`
77: }
78: function val(item: FloodRecord) { return (item.values ?? {}) as Record<string, unknown> }
79: function recordDate(item: FloodRecord) {
80:   const v = val(item)
81:   const raw = item.checkDate ?? (item.status === 'draft' ? (v.date ?? item.createdAt) : item.createdAt)
82:   return raw ? formatDateTime(String(raw)).slice(0, 10) : '—'
83: }
84: /* 编号：优先真实后端 inspectionNo，回退本地 id */
85: function recordNo(item: FloodRecord) { return item.inspectionNo ?? item.id }
86: /* 标题：求援用险情/等级；检查优先真实 complexName，回退 demo 地点 · 动作 */
87: function ticketTitle(item: FloodRecord) {
88:   const v = val(item)
89:   if (item.kind === 'rescue') return String(item.rescue?.dangerDesc ?? v.danger ?? '求援工单')
90:   const kind = item.kind as InspectionType
91:   if (item.complexName) return `${item.complexName} · ${ticketTitles[kind]}`
92:   return `${ticketPlaces[kind]} · ${ticketTitles[kind]}`
93: }
94: function urgentLevelText(item: FloodRecord) {
95:   const raw = item.rescue?.urgentLevel ?? val(item).level
96:   const map: Record<string, string> = { '1': '一般', '2': '紧急', '3': '特级' }
97:   if (raw == null || raw === '') return ''
98:   return map[String(raw)] ?? String(raw)
99: }
100: function statusText(item: FloodRecord) {
101:   if (item.kind === 'rescue') return urgentLevelText(item) || '求援'
102:   return item.status === 'draft' ? '待提交' : '已提交'
103: }
104: function urgentTone(item: FloodRecord) {
105:   return levelTone[urgentLevelText(item)] ?? 'done'
106: }
107: function statusClass(item: FloodRecord) {
108:   if (item.kind === 'rescue') return urgentTone(item) === 'critical' ? 'critical' : 'done'
109:   return item.status === 'draft' ? '' : 'done'
110: }
