5: 
6: function formatDateKey(obj) {
7:   if (!obj) return
8:   const keys = obj.DATE_KEY
9:   if (!keys) return
10:   keys.split(',').forEach((key) => {
11:     if (Object.keys(obj).includes(key)) {
12:       obj[key] = formatDateTime(obj[key], true, false)
13:     }
14:   })
15:   obj.DATE_KEY = undefined
16: }
17: 
18: function isRequestTimeout(err) {
19:   const msg = String(err?.errMsg || err?.message || '')
20:   return (/timeout|超时/i).test(msg) || err?.errno === 'ETIMEDOUT' || err?.code === 'ETIMEDOUT'
21: }
22: 
23: function normalizeRequestData(data, fallbackParams) {
24:   if (Object.prototype.toString.call(data).slice(8, -1).toLocaleLowerCase() !== 'object') {
25:     return data || fallbackParams
26:   }
27:   return Object.keys(data)
28:     .filter((key) => data[key] !== null && data[key] !== undefined && data[key] !== '')
29:     .reduce((acc, key) => ({ ...acc, [key]: data[key] }), {})
30: }
31: 
32: function logApiRequest({ tag, url, method, headers, params, response, duration, error }) {
33:   const logData = {
34:     请求地址: url,
35:     请求方法: method,
36:     请求头: headers,
37:     请求参数: params,
38:     耗时: duration != null ? `${duration}ms` : undefined,
39:     响应体: error || response,
40:   }
41:   const title = error ? `[${tag}] 请求失败 ${method} ${url}` : `[${tag}] ${method} ${url}`
42:   console.group(title)
43:   console.log(logData)
44:   console.groupEnd()
45: }
46: 
47: export function createHttpClient({ base, getToken, tag, supportNoReject = false, handleTimeout = false }) {
48:   const interceptorsRequest = (config) => {
49:     formatDateKey(config.params || config.data)
50:     config.headers = config.headers || {}
51: 
52:     const token = getToken()
53:     if (token) {
54:       config.headers.Authorization = `Bearer ${token}`
55:     }
56: 
57:     const payload = config.params || config.data
58:     const isPagingRequest
59:       = config.paging === true
60:       || payload && (payload.pageNum != null || payload.pageNo != null || payload.pageSize != null)
61:     if (isPagingRequest) {
62:       config.loading = false
63:     }
64: 
65:     if (config.loading === true) {
66:       uni.showLoading({
67:         title: config.loadingText || '加载中',
68:         mask: config.loadingMask !== false,
69:       })
70:     }
71: 
72:     return config
73:   }
74: 
75:   const interceptorsResponse = (response, config) => {
76:     if (config.loading === true) {
77:       uni.hideLoading()
78:     }
79:     const { data } = response
80:     if (supportNoReject && config.noReject) {
81:       return response
82:     }
83:     if (data.code == 401) {
84:       userStore.clear()
85:       if (window?.webkit || window?.android || window?.harmony) {
86:         appLogin()
87:       } else {
88:         uni.switchTab({ url: '/pages/index/home' })
89:       }
90:     }
91:     const shouldReject = data.code != 200 && data.code != 0 && data.code != 10000 && !(supportNoReject && config.noReject)
92:     if (shouldReject) {
93:       showToast(data.msg || '网络错误，请稍后再试')
94:       return Promise.reject(response)
95:     }
96:     return data
97:   }
98: 
99:   const httpRequest = (url, data, config = {}, method) => {
100:     const _c = interceptorsRequest(config)
101:     const requestData = normalizeRequestData(data, _c.params)
102:     const fullUrl = base + url
103: 
104:     return new Promise((resolve, reject) => {
105:       const startTime = Date.now()
106:       const logRequest = (extra = {}) => logApiRequest({
107:         tag,
108:         url: fullUrl,
109:         method,
110:         headers: _c.headers,
111:         params: requestData,
112:         duration: Date.now() - startTime,
113:         ...extra,
114:       })
115: 
116:       uni.request({
117:         url: fullUrl,
118:         method,
119:         timeout: 60 * 1000,
120:         data: requestData,
121:         header: _c.headers,
122:         success: (res) => {
123:           try {
124:             const data = interceptorsResponse(res, config)
125:             logRequest({ response: data })
126:             resolve(data)
127:           } catch (e) {
128:             logRequest({ response: res.data, error: e })
129:             reject(e)
130:           }
131:         },
132:         fail: (err) => {
133:           if (config.loading === true) {
134:             uni.hideLoading()
135:           }
136:           logRequest({ error: err })
137:           if (handleTimeout && isRequestTimeout(err)) {
138:             showToast('请求超时，请退出当前页面重新进入', 3500)
139:           }
140:           reject(err)
141:         },
142:       })
143:     })
144:   }
145: 
146:   const file = (url, data, config = {}) => {
147:     const _c = interceptorsRequest(config)
148:     const fullUrl = base + url
149:     const fileFieldName = data.name || 'file'
150:     // H5 签字等场景只传 File 对象；小程序/App 走 filePath
151:     const uploadFiles = data.files
152:       || (!data.filePath && data.file ? [{ name: fileFieldName, file: data.file }] : undefined)
153: 
154:     return new Promise((resolve, reject) => {
155:       const startTime = Date.now()
156:       const logRequest = (extra = {}) => logApiRequest({
157:         tag: `${tag}-FILE`,
158:         url: fullUrl,
159:         method: 'POST',
160:         headers: _c.headers,
161:         params: data,
162:         duration: Date.now() - startTime,
163:         ...extra,
164:       })
165: 
166:       uni.uploadFile({
167:         url: fullUrl,
168:         header: _c.headers,
169:         files: uploadFiles,
170:         formData: data.formData,
171:         name: fileFieldName,
172:         file: uploadFiles ? undefined : data.file,
173:         filePath: uploadFiles ? undefined : data.filePath,
174:         success: (res) => {
175:           try {
176:             res.data = JSON.parse(res.data)
177:             const responseData = interceptorsResponse(res, config)
178:             logRequest({ response: responseData })
179:             resolve(responseData)
180:           } catch (e) {
181:             logRequest({ response: res.data, error: e })
182:             reject(e)
183:           }
184:         },
185:         fail: (err) => {
186:           logRequest({ error: err })
187:           if (handleTimeout && isRequestTimeout(err)) {
188:             showToast('请求超时，请退出当前页面重新进入', 3500)
189:           }
190:           reject(err)
191:         },
192:       })
193:     })
194:   }
195: 
196:   return {
197:     post: (url, data, config) => httpRequest(url, data, config, 'POST'),
198:     get: (url, config) => httpRequest(url, config?.params, config, 'GET'),
199:     put: (url, data, config) => httpRequest(url, data, config, 'PUT'),
200:     file,
201:   }
202: }

