1: // 纯 JS AES-256-CBC + PKCS5(PKCS7) 加密，输出 base64。
2: // 与后端 com.zhishu.common.core.utils.AESUtil 对齐：
3: //   key = 'A-16-Byte-keyValA-16-Byte-keyVal' (32字节 => AES-256)
4: //   iv  = 'A-16-Byte-String' (16字节)
5: // 仅实现加密（登录密码用），解密可选。
6: 
7: type Word = number[]
8: const SBOX: number[] = []
9: const INV_SBOX: number[] = []
10: const RCON: number[] = []
11: ;(function initTables() {
12:   // 生成 S-box（基于 GF(2^8) 乘法逆 + 仿射变换），避免手抄 256 项
13:   const p = new Uint8Array(256)
14:   const q = new Uint8Array(256)
15:   let x = 1
16:   for (let i = 0; i < 255; i++) {
17:     p[i] = x
18:     // x * 3 in GF(2^8)
19:     x ^= (x << 1) ^ (x & 0x80 ? 0x1b : 0)
20:     x &= 0xff
21:     // q[i] = x^-1 track via p; we build log/antilog
22:   }
23:   // 用对数表构造逆
24:   const log = new Uint8Array(256)
25:   const exp = new Uint8Array(256)
26:   let expx = 1
27:   for (let i = 0; i < 255; i++) {
28:     exp[i] = expx
29:     log[expx] = i
30:     // expx *= 3
31:     expx ^= (expx << 1) ^ (expx & 0x80 ? 0x1b : 0)
32:     expx &= 0xff
33:   }
34:   exp[255] = exp[0]
35:   for (let i = 2; i < 256; i++) {
36:     const inv = exp[(255 - log[i]) % 255]
37:     let s = inv
38:     let s2 = ((s << 1) | (s >> 7)) & 0xff
39:     let s3 = ((s2 << 1) | (s2 >> 7)) & 0xff
40:     let s4 = ((s3 << 1) | (s3 >> 7)) & 0xff
41:     let s5 = ((s4 << 1) | (s4 >> 7)) & 0xff
42:     let r = s ^ s2 ^ s3 ^ s4 ^ s5 ^ 0x63
43:     SBOX[i] = r & 0xff
44:     INV_SBOX[r & 0xff] = i
45:   }
46:   SBOX[0] = 0x63
47:   INV_SBOX[0x63] = 0
48:   let rcon = 1
49:   for (let i = 0; i < 15; i++) { RCON[i] = rcon; rcon = gmul(rcon, 2) }
50: })()
51: 
52: function gmul(a: number, b: number): number {
53:   let p = 0
54:   for (let i = 0; i < 8; i++) {
55:     if (b & 1) p ^= a
56:     const hi = a & 0x80
57:     a = (a << 1) & 0xff
58:     if (hi) a ^= 0x1b
59:     b >>= 1
60:   }
61:   return p & 0xff
62: }
63: 
64: function xtime(a: number): number { return ((a << 1) ^ (a & 0x80 ? 0x1b : 0)) & 0xff }
65: 
66: function expandKey(key: number[]): number[][] {
67:   const Nk = key.length / 4 // 8 for 256
68:   const Nr = Nk + 6 // 14 for 256
69:   const w: number[][] = []
70:   for (let i = 0; i < Nk; i++) w[i] = [key[4 * i], key[4 * i + 1], key[4 * i + 2], key[4 * i + 3]]
71:   for (let i = Nk; i < 4 * (Nr + 1); i++) {
72:     let temp = w[i - 1].slice()
73:     if (i % Nk === 0) {
74:       temp = [temp[1], temp[2], temp[3], temp[0]] // RotWord
75:       temp = temp.map(b => SBOX[b]) // SubWord
76:       temp[0] ^= RCON[i / Nk - 1]
77:     } else if (Nk > 6 && i % Nk === 4) {
78:       temp = temp.map(b => SBOX[b])
79:     }
80:     w[i] = w[i - Nk].map((b, j) => b ^ temp[j])
81:   }
82:   const roundKeys: number[][] = []
83:   for (let r = 0; r <= Nr; r++) {
84:     const rk: number[] = []
85:     for (let c = 0; c < 4; c++) rk.push(...w[4 * r + c])
86:     roundKeys.push(rk)
87:   }
88:   return roundKeys
89: }
90: 
91: function addRoundKey(state: number[], rk: number[]) { for (let i = 0; i < 16; i++) state[i] ^= rk[i] }
92: 
93: function subBytes(state: number[]) { for (let i = 0; i < 16; i++) state[i] = SBOX[state[i]] }
94: function invSubBytes(state: number[]) { for (let i = 0; i < 16; i++) state[i] = INV_SBOX[state[i]] }
95: 
96: function shiftRows(s: number[]) {
97:   // 列主序：state[c*4+r]
98:   for (let r = 1; r < 4; r++) {
99:     const row = [s[r], s[4 + r], s[8 + r], s[12 + r]]
100:     const sh = row.slice(r).concat(row.slice(0, r))
101:     s[r] = sh[0]; s[4 + r] = sh[1]; s[8 + r] = sh[2]; s[12 + r] = sh[3]
102:   }
103: }
104: function invShiftRows(s: number[]) {
105:   for (let r = 1; r < 4; r++) {
106:     const row = [s[r], s[4 + r], s[8 + r], s[12 + r]]
107:     const sh = row.slice(4 - r).concat(row.slice(0, 4 - r))
108:     s[r] = sh[0]; s[4 + r] = sh[1]; s[8 + r] = sh[2]; s[12 + r] = sh[3]
109:   }
110: }
111: function mixColumns(s: number[]) {
112:   for (let c = 0; c < 4; c++) {
113:     const i = 4 * c
114:     const a0 = s[i], a1 = s[i + 1], a2 = s[i + 2], a3 = s[i + 3]
115:     s[i] = gmul(a0, 2) ^ gmul(a1, 3) ^ a2 ^ a3
116:     s[i + 1] = a0 ^ gmul(a1, 2) ^ gmul(a2, 3) ^ a3
117:     s[i + 2] = a0 ^ a1 ^ gmul(a2, 2) ^ gmul(a3, 3)
118:     s[i + 3] = gmul(a0, 3) ^ a1 ^ a2 ^ gmul(a3, 2)
119:   }
120: }
121: function invMixColumns(s: number[]) {
122:   for (let c = 0; c < 4; c++) {
123:     const i = 4 * c
124:     const a0 = s[i], a1 = s[i + 1], a2 = s[i + 2], a3 = s[i + 3]
125:     s[i] = gmul(a0, 14) ^ gmul(a1, 11) ^ gmul(a2, 13) ^ gmul(a3, 9)
126:     s[i + 1] = gmul(a0, 9) ^ gmul(a1, 14) ^ gmul(a2, 11) ^ gmul(a3, 13)
127:     s[i + 2] = gmul(a0, 13) ^ gmul(a1, 9) ^ gmul(a2, 14) ^ gmul(a3, 11)
128:     s[i + 3] = gmul(a0, 11) ^ gmul(a1, 13) ^ gmul(a2, 9) ^ gmul(a3, 14)
129:   }
130: }
131: 
132: function encryptBlock(input: number[], roundKeys: number[][]): number[] {
133:   const s = input.slice()
134:   addRoundKey(s, roundKeys[0])
135:   const Nr = roundKeys.length - 1
136:   for (let r = 1; r < Nr; r++) {
137:     subBytes(s); shiftRows(s); mixColumns(s); addRoundKey(s, roundKeys[r])
138:   }
139:   subBytes(s); shiftRows(s); addRoundKey(s, roundKeys[Nr])
140:   return s
141: }
142: function decryptBlock(input: number[], roundKeys: number[][]): number[] {
143:   const s = input.slice()
144:   const Nr = roundKeys.length - 1
145:   addRoundKey(s, roundKeys[Nr])
146:   for (let r = Nr - 1; r >= 1; r--) {
147:     invShiftRows(s); invSubBytes(s); addRoundKey(s, roundKeys[r]); invMixColumns(s)
148:   }
149:   invShiftRows(s); invSubBytes(s); addRoundKey(s, roundKeys[0])
150:   return s
151: }
152: 
153: function utf8Bytes(str: string): number[] {
154:   const out: number[] = []
155:   for (const ch of str) {
156:     const cp = ch.codePointAt(0) as number
157:     if (cp < 0x80) out.push(cp)
158:     else if (cp < 0x800) out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f))
159:     else if (cp < 0x10000) out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f))
160:     else out.push(0xf0 | (cp >> 18), 0x80 | ((cp >> 12) & 0x3f), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f))
161:   }
162:   return out
163: }
164: function bytesToUtf8(bytes: number[]): string {
165:   let out = ''
166:   for (let i = 0; i < bytes.length;) {
167:     const b = bytes[i]
168:     if (b < 0x80) { out += String.fromCharCode(b); i++ }
169:     else if ((b & 0xe0) === 0xc0) { out += String.fromCharCode(((b & 0x1f) << 6) | (bytes[i + 1] & 0x3f)); i += 2 }
170:     else if ((b & 0xf0) === 0xe0) { out += String.fromCharCode(((b & 0x0f) << 12) | ((bytes[i + 1] & 0x3f) << 6) | (bytes[i + 2] & 0x3f)); i += 3 }
171:     else { const cp = ((b & 0x07) << 18) | ((bytes[i + 1] & 0x3f) << 12) | ((bytes[i + 2] & 0x3f) << 6) | (bytes[i + 3] & 0x3f); out += String.fromCodePoint(cp); i += 4 }
172:   }
173:   return out
174: }
175: 
176: const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
177: function base64Encode(bytes: number[]): string {
178:   let out = ''
179:   for (let i = 0; i < bytes.length; i += 3) {
180:     const b0 = bytes[i], b1 = bytes[i + 1] ?? 0, b2 = bytes[i + 2] ?? 0
181:     out += B64[b0 >> 2] + B64[((b0 & 3) << 4) | (b1 >> 4)]
182:     out += i + 1 < bytes.length ? B64[((b1 & 15) << 2) | (b2 >> 6)] : '='
183:     out += i + 2 < bytes.length ? B64[b2 & 63] : '='
184:   }
185:   return out
186: }
187: function base64Decode(str: string): number[] {
188:   const clean = str.replace(/[^A-Za-z0-9+/]/g, '')
189:   const out: number[] = []
190:   for (let i = 0; i < clean.length; i += 4) {
191:     const c0 = B64.indexOf(clean[i]), c1 = B64.indexOf(clean[i + 1]), c2 = B64.indexOf(clean[i + 2]), c3 = B64.indexOf(clean[i + 3])
192:     out.push((c0 << 2) | (c1 >> 4))
193:     if (c2 >= 0) out.push(((c1 & 15) << 4) | (c2 >> 2))
194:     if (c3 >= 0) out.push(((c2 & 3) << 6) | c3)
195:   }
196:   return out
197: }
