199: function pkcs7Pad(data: number[]): number[] {
200:   const pad = 16 - (data.length % 16)
201:   return data.concat(new Array(pad).fill(pad))
202: }
203: function pkcs7Unpad(data: number[]): number[] {
204:   const pad = data[data.length - 1]
205:   if (pad < 1 || pad > 16) return data
206:   return data.slice(0, data.length - pad)
207: }
208: 
209: const DEFAULT_KEY = 'A-16-Byte-keyValA-16-Byte-keyVal'
210: const DEFAULT_IV = 'A-16-Byte-String'
211: 
212: export function aesEncrypt(plain: string, key = DEFAULT_KEY, iv = DEFAULT_IV): string {
213:   const roundKeys = expandKey(utf8Bytes(key))
214:   const ivBytes = utf8Bytes(iv)
215:   const data = pkcs7Pad(utf8Bytes(plain))
216:   const out: number[] = []
217:   let prev = ivBytes
218:   for (let i = 0; i < data.length; i += 16) {
219:     const block = data.slice(i, i + 16).map((b, j) => b ^ prev[j])
220:     const enc = encryptBlock(block, roundKeys)
221:     out.push(...enc)
222:     prev = enc
223:   }
224:   return base64Encode(out)
225: }
