227: export function aesDecrypt(cipherB64: string, key = DEFAULT_KEY, iv = DEFAULT_IV): string {
228:   const roundKeys = expandKey(utf8Bytes(key))
229:   const ivBytes = utf8Bytes(iv)
230:   const data = base64Decode(cipherB64)
231:   const out: number[] = []
232:   let prev = ivBytes
233:   for (let i = 0; i < data.length; i += 16) {
234:     const block = data.slice(i, i + 16)
235:     const dec = decryptBlock(block, roundKeys).map((b, j) => b ^ prev[j])
236:     out.push(...dec)
237:     prev = block
238:   }
239:   return bytesToUtf8(pkcs7Unpad(out))
240: }

