44: .side-tab{height:76px;text-align:center;border-radius:12px;background:var(--c-fill);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;font-size:14px;position:relative}
45: .side-tab-image{width:20px;height:20px}
46: .side-tab.active{background:var(--c-brand-soft);color:#004fd0}
