49: .section-title{height:38px;padding:0 12px;background:var(--c-surface);border-radius:var(--r-ctl);display:flex;align-items:center;justify-content:space-between;box-shadow:var(--shadow-card);font-size:16px;margin-bottom:8px}
50: .section-title-text{font-weight:700}
51: .section-title-count{font-size:13px;color:var(--c-text-2);background:var(--c-fill-strong);padding:2px 8px;border-radius:99px}
52: .app-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
53: .app-card{height:116px;text-align:center;background:var(--c-surface);border-radius:var(--r-card);box-shadow:var(--shadow-card);display:flex;flex-direction:column;align-items:center;justify-content:center}
54: .icon-well{width:48px;text-align:center;height:48px;border-radius:16px;display:grid;place-items:center;margin-bottom:6px;background:#eff6ffcc}
