56: .tone-1{background:#eef2ffcc}
57: .tone-2{background:#f0fdfacc}
58: .tone-3{background:#fffbeacc}
59: .app-card-title{font-size:16px;line-height:20px;font-weight:700}
60: .app-card-sub{font-size:12px;color:var(--c-text-2);line-height:14px}
61: 
