/**
 * 门户（首页 / 我的）功能接口层。
 *
 * 接口路径与入参参照「苏住房C」zhi2-mobile-shimin 的 src/api/*.js：
 *   - article.js / articleV1.js  -> /v2.0/article/richText/page、/v2.0/article/richText/{id}
 *   - system.js                  -> /v2.0/system/banner/page、/v2.0/system/msg/pageByRegion、
 *                                  /v2.0/system/msg/getByMsgIdNoPermissions/{msgId}、
 *                                  /v2.0/system/pageNavigation/page
 *   - msg.js                     -> /v2.0/msg/msg/page、/v2.0/msg/msg/msgNum、
 *                                  /v2.0/msg/msgRange/{id}、/v2.0/msg/msgRange/updateReadFlag
 *   - property.js                -> /v2.0/property/msg/page（app 公告）
 *   - security.js                -> /v2.0/security/ctAuth/profile、/v2.0/security/ctAuth/logout、
 *                                  /v2.0/security/ctUserRealName/getAuditByToken
 *   - 苏住房后端 service-expand  -> /v2.0/article/portal/getStudyList?tab=1..5（学习园地）
 *   - 苏住房后端 common-flowable -> /v2.0/flowable/task/taskCount、/v2.0/flowable/task/todoTaskList
 *
 * 本项目网关前缀为 /api（nginx 反代），故统一使用 /v2.0/... 路径，与防汛接口保持同源同头。
 * 分页接口返回「根级」 {total,rows,code,msg}（非 data 包裹），因此统一 raw:true 后手动解包。
 */
import { request } from '../utils/request'

export interface PageResult<T> { total: number; rows: T[] }

function queryString(params: Record<string, unknown> = {}): string {
  const q = new URLSearchParams()
  Object.entries(params).forEach(([k, v]) => {
    if (v !== undefined && v !== null && v !== '') q.set(k, String(v))
  })
  const s = q.toString()
  return s ? `?${s}` : ''
}

/** 统一解包分页响应：兼容根级 PageResult 与 {code,msg,data} 两种包裹 */
async function page<T>(path: string, params: Record<string, unknown> = {}): Promise<PageResult<T>> {
  const body = await request<unknown>(`${path}${queryString(params)}`, { raw: true })
  const b = (body ?? {}) as {
    total?: number | string; rows?: T[]
    data?: { total?: number | string; rows?: T[] }
    code?: number; msg?: string
  }
  if (b.code !== undefined && b.code !== 200 && b.code !== 0) throw new Error(b.msg || `接口异常（code ${b.code}）`)
  const src = b.data && !Array.isArray(b.rows) ? b.data : b
  return { total: Number(src?.total ?? 0) || 0, rows: Array.isArray(src?.rows) ? src.rows : [] }
}

/** 详情/单对象接口：走 request 的 {code,msg,data} 解包 */
function detail<T>(path: string, params: Record<string, unknown> = {}, headers?: Record<string, string>): Promise<T> {
  return request<T>(`${path}${queryString(params)}`, headers ? { headers } : {})
}

// ============ 首页：学习园地 ============
/** tab: 1政策法规 2流程指南 3在线课堂 4常见问题 5经典案例 */
export function getStudyList(params: { tab: string | number; pageNum?: number; pageSize?: number }): Promise<PageResult<Record<string, unknown>>> {
  return page('/v2.0/article/portal/getStudyList', params as Record<string, unknown>)
}

/** 文章分页（新闻公告 / 政策法规等富文本） */
export function articlePage(params: Record<string, unknown> = {}): Promise<PageResult<Record<string, unknown>>> {
  return page('/v2.0/article/richText/page', { type: '6', publishState: 1, displayLocation: '3', ...params })
}

/** 文章详情 */
export function richTextDetail(richTextId: string): Promise<Record<string, unknown>> {
  return detail(`/v2.0/article/richText/${encodeURIComponent(richTextId)}`)
}

/** 常见问题 / 在线课堂列表与详情（苏住房C article.js） */
export function articleProblemPage(params: Record<string, unknown> = {}): Promise<PageResult<Record<string, unknown>>> {
  return page('/v2.0/article/problem/page', params)
}
export function articleVideoPage(params: Record<string, unknown> = {}): Promise<PageResult<Record<string, unknown>>> {
  return page('/v2.0/article/video/page', params)
}
export function articleVideoDetail(videoId: string): Promise<Record<string, unknown>> {
  return detail(`/v2.0/article/video/${encodeURIComponent(videoId)}/article`)
}

// ============ 首页：通知公告 / 新闻公告 ============
/** app 公告列表（苏住房C property.js appMsg，displayLocation: 1小区 2社区 3街道） */
export function appMsg(params: Record<string, unknown> = {}): Promise<PageResult<Record<string, unknown>>> {
  return page('/v2.0/property/msg/page', { isEffective: '1', ...params })
}

/** 依据行政区域查询公告发布列表（苏住房C system.js pageByRegion） */
export function pageByRegion(params: Record<string, unknown> = {}): Promise<PageResult<Record<string, unknown>>> {
  return page('/v2.0/system/msg/pageByRegion', params)
}

/** 公告详情（无权限控制，H5 可读） */
export function getByMsgIdNoPermissions(msgId: string): Promise<Record<string, unknown>> {
