/**
 * 门户（首页 / 我的）数据服务：把「苏住房C」接口接到页面视图模型上。
 *
 * 模式约定（与项目既有 dataMode 一致）：
 * - demo 模式 / 未配置 / 未登录（无 token）时：直接返回设计稿静态数据，不发请求；
 * - remote 模式且已登录：调用真实接口；接口异常时静默回退静态数据，不弹 toast
 *   （符合「无数据是常态而非异常」的项目约定，也保证视觉回归用例稳定）。
 */
import * as api from '../api/portal'
import { isDemoDataMode } from './dataMode'
import { getToken, isConfigured } from './request'
import { PORTAL_TABS, TAB_CODES } from '../composables/usePortalNav'
import { SEED_HOME, SEED_MINE, seedList, seedDetail } from '../mock/portalSeed'
import type {
  PortalArticle, PortalHomeData, PortalListResult, PortalListItem, PortalMineData,
  PortalDetail, PortalListType, PortalDetailType,
} from '../types/portal'

/** 是否走真实接口：remote 模式 + 已配置 /api + 已登录 */
export function usePortalApi(): boolean {
  return !isDemoDataMode() && isConfigured() && Boolean(getToken())
}

type Row = Record<string, unknown>
const s = (v: unknown): string => v == null ? '' : String(v)
const first = (...vals: unknown[]): string => {
  for (const v of vals) { const t = s(v).trim(); if (t) return t }
  return ''
}
const num = (v: unknown): number => { const n = Number(v); return Number.isFinite(n) ? n : 0 }
const dateOnly = (v: unknown): string => first(v).slice(0, 10)
const dateTime = (v: unknown): string => first(v).slice(0, 16)

/** 相对媒体地址：仅保留同源可访问的 /static 资源与绝对 URL，避免拼错域名 */
export function resolveMedia(raw: unknown): string {
  const v = first(raw)
  if (!v) return ''
  if (/^(data:|blob:|https?:\/\/)/i.test(v)) return v
  if (v.includes('/static/')) return v.startsWith('/') ? v : `/${v}`
  return ''
}

function toArticle(row: Row, detailType: PortalDetailType = 'article'): PortalArticle {
  const id = first(row.richTextId, row.id, row.msgId, row.problemId, row.videoId)
  const title = first(row.title, row.msgTitle, row.problemTitle, row.problemName)
  const publish = first(row.publishTime, row.createTime, row.publishDate)
  const read = first(row.readNum, row.viewCount, row.learnNum, row.studyNum)
  return {
    id, title,
    tag: first(row.typeName, row.tagName) || undefined,
    meta: dateOnly(publish) || first(row.source, row.publishUser),
    trailing: read ? `${read}阅读` : undefined,
    image: resolveMedia(first(row.previewSite, row.coverImage, row.coverImg, row.iconPath)) || undefined,
    source: first(row.source, row.publishUnit, row.publishUser) || undefined,
    publishTime: dateTime(publish) || undefined,
    summary: first(row.summary, row.abstract, row.description) || undefined,
    detailType,
    linkUrl: first(row.urlSite, row.linkUrl) || undefined,
    raw: row,
  }
}

function toNotice(row: Row): PortalListItem {
  return {
    id: first(row.msgId, row.id),
    title: first(row.msgTitle, row.title),
    typeName: first(row.displayLocationName, row.typeName) || undefined,
    date: dateOnly(first(row.publishTime, row.createTime)),
    publisher: first(row.publishUnit, row.publisher),
    summary: first(row.msgContent, row.summary),
    detailType: 'notice',
    raw: row,
  }
}

function toMessage(row: Row): PortalListItem {
  return {
    id: first(row.msgId, row.id),
    rangeId: first(row.msgRangeId, row.rangeId, row.msgId, row.id),
    title: first(row.msgTitle, row.title, row.busCodeName),
    date: dateTime(first(row.sendTime, row.createTime)),
    abstract: first(row.msgData, row.msgContent, row.abstract),
    type: first(row.busCodeName, row.typeName) || undefined,
    readFlag: row.readFlag as number | string | undefined,
    msgChannel: row.msgChannel as number | string | undefined,
    msgUrl: first(row.msgUrl) || undefined,
    detailType: 'message',
    raw: row,
  }
}

function toTask(row: Row): PortalListItem {
  return {
    id: first(row.taskId, row.id),
    title: first(row.submitTittle, row.procDefName, row.taskName, row.name),
    subtitle: first(row.menuName, row.startDeptName, row.taskName) || undefined,
    date: dateTime(first(row.startTime, row.createTime)),
    status: '待处理',
    menuName: first(row.menuName) || undefined,
    busCode: first(row.busCode) || undefined,
    detailId: first(row.detailId) || undefined,
    path: first(row.path) || undefined,
    detailType: 'task',
    raw: row,
  }
}

/** 静默包装：接口失败返回兜底值，不弹 toast */
async function safe<T>(work: () => Promise<T>, fallback: T): Promise<T> {
  if (!usePortalApi()) return fallback
  try { return await work() } catch { return fallback }
}

/** 首页聚合数据：通知公告 / 待办数 / 学习园地 / 新闻公告 / 横幅 */
export async function fetchHome(): Promise<PortalHomeData> {
  const seed = SEED_HOME
  const [noticeRow, taskCount, studyRows, newsRows, bannerRows] = await Promise.all([
    safe(async () => (await api.appMsg({ pageNum: 1, pageSize: 1, msgType: '' })).rows[0] as Row | undefined, undefined as Row | undefined),
    safe(async () => api.getTaskCount(), undefined as { todoNum?: number } | undefined),
    safe(async () => (await api.getStudyList({ tab: 1, pageNum: 1, pageSize: 2 })).rows as Row[], undefined as Row[] | undefined),
    safe(async () => (await api.articlePage({ pageNum: 1, pageSize: 3 })).rows as Row[], undefined as Row[] | undefined),
    safe(async () => (await api.getBannerList({ pageNum: 1, pageSize: 1 })).rows as Row[], undefined as Row[] | undefined),
  ])

  const notice = noticeRow
    ? { id: first(noticeRow.msgId, noticeRow.id) || seed.notice.id, title: first(noticeRow.msgTitle, noticeRow.title) || seed.notice.title }
    : seed.notice
  const todoCount = taskCount && num(taskCount.todoNum) > 0 ? num(taskCount.todoNum) : seed.todoCount
  const study = studyRows?.length
    ? { ...seed.study, [PORTAL_TABS[0]]: studyRows.slice(0, 2).map(r => toArticle(r)) }
    : seed.study
  const news = newsRows?.length ? newsRows.slice(0, 3).map(r => toArticle(r)) : seed.news
  const bannerRow = bannerRows?.[0]
  const banner = bannerRow
    ? {
        small: seed.banner.small,
        title: first(bannerRow.name, bannerRow.bannerName) || seed.banner.title,
        sub: seed.banner.sub,
        linkUrl: first(bannerRow.linkUrl, bannerRow.url) || undefined,
      }
    : seed.banner

  return { notice, todoCount, todoText: seed.todoText, banner, tabs: [...PORTAL_TABS], study, news }
}

/** 学习园地切换 tab：按 tab 编码拉真实列表 */
export async function fetchStudyTab(tab: string): Promise<PortalArticle[]> {
  const seed = SEED_HOME.study[tab] ?? SEED_HOME.study[PORTAL_TABS[0]]
  return safe(async () => {
    const code = TAB_CODES[tab] ?? 1
    const res = code === 3
      ? await api.articleVideoPage({ pageNum: 1, pageSize: 2, status: 1 })
      : code === 4
        ? await api.articleProblemPage({ pageNum: 1, pageSize: 2, status: 1 })
        : await api.getStudyList({ tab: code, pageNum: 1, pageSize: 2 })
    const rows = (res.rows ?? []) as Row[]
    if (!rows.length) return seed
    const dtype: PortalDetailType = code === 3 ? 'video' : code === 4 ? 'problem' : 'article'
    return rows.slice(0, 2).map(r => toArticle(r, dtype))
  }, seed)
}

/** 我的页：用户信息 / 未读消息数 / 待办数 */
export async function fetchMine(): Promise<PortalMineData> {
  const [profile, unread, taskCount] = await Promise.all([
    safe(async () => api.queryUser(), undefined as Row | undefined),
    safe(async () => api.getMsgNum({ readFlag: 0, projectType: 1 }), undefined as unknown),
    safe(async () => api.getTaskCount(), undefined as { todoNum?: number } | undefined),
  ])
  const name = first(profile?.nickName, profile?.realName, profile?.userName)
  const loginName = first(profile?.userId, profile?.userName)
  const user = {
    name: name || SEED_MINE.user.name,
    loginName: loginName || SEED_MINE.user.loginName,
    verified: profile ? first(profile.realNameStatus, profile.isReal) === '1' || SEED_MINE.user.verified : SEED_MINE.user.verified,
    phone: first(profile?.phone) || undefined,
    avatar: resolveMedia(profile?.avatar) || undefined,
  }
  const unreadCount = unread === undefined ? SEED_MINE.unread : num(unread)
  return { user, unread: unreadCount, todoNum: taskCount && num(taskCount.todoNum) > 0 ? num(taskCount.todoNum) : SEED_MINE.todoNum }
}

/** 通用列表分页 */
export async function fetchList(type: PortalListType, pageNum: number, pageSize: number, tab?: string): Promise<PortalListResult> {
  const seedItems = seedList(type, tab)
  const seed: PortalListResult = { items: seedItems, total: seedItems.length, hasMore: false }
  return safe(async () => {
    let res: { total: number; rows: Row[] }
    switch (type) {
      case 'notice':
        res = await api.appMsg({ pageNum, pageSize, msgType: '' })
        break
      case 'news':
        res = await api.articlePage({ pageNum, pageSize })
        break
      case 'study': {
        const code = TAB_CODES[tab ?? PORTAL_TABS[0]] ?? 1
        res = code === 3 ? await api.articleVideoPage({ pageNum, pageSize, status: 1 })
          : code === 4 ? await api.articleProblemPage({ pageNum, pageSize, status: 1 })
            : await api.getStudyList({ tab: code, pageNum, pageSize })
        break
      }
      case 'message':
        res = await api.getMessageList({ pageNum, pageSize, projectType: 1 })
        break
      case 'task':
        res = await api.getTodoTaskList({ pageNum, pageSize })
        break
    }
    const rows = (res.rows ?? []) as Row[]
    const items = rows.map(r => type === 'notice' ? toNotice(r)
      : type === 'message' ? toMessage(r)
        : type === 'task' ? toTask(r)
          : toArticle(r, type === 'study' && TAB_CODES[tab ?? PORTAL_TABS[0]] === 3 ? 'video'
            : type === 'study' && TAB_CODES[tab ?? PORTAL_TABS[0]] === 4 ? 'problem' : 'article'))
    if (!items.length && pageNum === 1) return seed
    return { items, total: num(res.total), hasMore: pageNum * pageSize < num(res.total) }
  }, seed)
}

/** 通用详情：按 type 走对应详情接口，失败回退静态正文 */
export async function fetchDetail(type: PortalDetailType, id: string): Promise<PortalDetail> {
  const fallback = seedDetail(type, id)
  return safe(async () => {
    let row: Row
    switch (type) {
      case 'video': row = await api.articleVideoDetail(id); break
      case 'problem': row = await api.articleProblemDetail(id); break
      case 'msg': row = await api.getByMsgIdNoPermissions(id); break
      case 'notice': row = await api.getByMsgIdNoPermissions(id); break
      case 'message': row = await api.getMessageDetail(id); break
      case 'task': return fallback
      default: row = await api.richTextDetail(id); break
    }
    const title = first(row.title, row.msgTitle, row.problemTitle, row.problemName) || fallback.title
    const content = first(row.content, row.msgContent, row.articleContent, row.problemAnswer, row.answer)
    const meta = dateTime(first(row.publishTime, row.createTime, row.sendTime)) || fallback.meta
    const source = first(row.source, row.publishUnit, row.publishUser, row.publisher) || fallback.source
    return {
      id, title, meta, source,
      content: content || fallback.content,
      linkUrl: first(row.urlSite, row.linkUrl) || undefined,
      fields: type === 'task' ? fallback.fields : undefined,
    }
  }, fallback)
}

/** 退出登录：先请求后端注销，再清本地令牌（后端失败不阻断退出） */
export async function portalSignOut(): Promise<void> {
  if (usePortalApi()) {
    try { await api.signOut() } catch { /* 忽略后端注销失败，仍清本地令牌 */ }
  }
}

